18	#[clap(
19	    name = "append_row",
20	    about = "Measure time it takes to append rows to a row group"
21	)]
22	struct Opt {
23	    /// Number of repetitions of the test
24	    #[clap(short, long, default_value = "5")]
25	    niter: usize,
26	    /// Number of rows
27	    #[clap(short, long, default_value = "10000")]
28	    rows: usize,
29	    /// Number of blocks
30	    #[clap(short, long, default_value = "300")]
31	    blocks: usize,
32	    /// Number of ids
33	    #[clap(short, long, default_value = "500")]
34	    ids: usize,
35	}
